package test
import future.keywords.and

p if {
  { a := 1; a > 0 } and { a := 2; a > 1 }
}

package test
import future.keywords.or

p if {
  { a := 0; a > 0 } or { a := 5; a > 0 }
}

package test
import future.keywords.and

# outer `a` must not leak into the operand body and vice-versa.
p if {
  a := -100
  { a := 1; a > 0 } and { a := 2; a > 1 }
  a == -100
}

package test
import future.keywords.and

p if {
  { some n in [1, 2, 3]; n > 2 } and { some n in [10, 20, 30]; n > 20 }
}

package test
import future.keywords.and
import future.keywords.or

p if {
  { a := 1; a > 0 } and { { a := 2; a > 1 } or { a := 3; a > 5 } }
}
